{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_CoUnitTemporalMode :
(
	EVENTUALLY_TRUE := 0,
	REMAINS_TRUE,
	REMAINS_FALSE,
	STEP
) BYTE;
END_TYPE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_CoUnitTemporalResult :
(
	WAITING := 0,
	PASSED,
	FAILED,
	CANCELLED,
	REJECTED
) BYTE;
END_TYPE

TYPE ST_CoUnitFixtureKey :
STRUCT
	RunId : STRING(63);
	SuiteId : STRING(63);
	CaseId : STRING(63);
	RowKey : STRING(63);
	AttemptId : STRING(63);
	StepId : STRING(63);
END_STRUCT
END_TYPE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_CoUnitFixtureCallback :
(
	PENDING := 0,
	PASSED,
	FAILED
) BYTE;
END_TYPE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_CoUnitFixturePhase :
(
	IDLE := 0,
	SETUP,
	BODY,
	CLEANUP,
	COMPLETE
) BYTE;
END_TYPE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_CoUnitFixtureCause :
(
	NONE := 0,
	SETUP_FAILED,
	BODY_FAILED,
	CANCELLED,
	PHASE_TIMEOUT
) BYTE;
END_TYPE

{attribute 'qualified_only'}
{attribute 'strict'}
TYPE E_CoUnitFixtureOutcome :
(
	NOT_RUN := 0,
	PENDING,
	PASSED,
	FAILED,
	INCOMPLETE
) BYTE;
END_TYPE

ST.xhtml:
Start := FALSE;
IF _active AND (State = E_CoUnitTemporalResult.WAITING) THEN RETURN; END_IF
IF _active AND (Key.RunId = _key.RunId) AND (Key.SuiteId = _key.SuiteId) AND (Key.CaseId = _key.CaseId)
	AND (Key.RowKey = _key.RowKey) AND (Key.AttemptId = _key.AttemptId) AND (Key.StepId = _key.StepId) THEN RETURN; END_IF
IF (Now < LTIME#0ns) OR (Duration < LTIME#0ns) THEN RETURN; END_IF
IF Now > (LTIME#9223372036854775807ns - Duration) THEN RETURN; END_IF
IF (Mode <> E_CoUnitTemporalMode.EVENTUALLY_TRUE)
	AND (Mode <> E_CoUnitTemporalMode.REMAINS_TRUE)
	AND (Mode <> E_CoUnitTemporalMode.REMAINS_FALSE)
	AND (Mode <> E_CoUnitTemporalMode.STEP) THEN RETURN; END_IF
_key := Key;
_mode := Mode;
_startedAt := Now;
_lastNow := Now;
_duration := Duration;
_deadline := Now + Duration;
_active := TRUE;
Resolved := FALSE;
State := E_CoUnitTemporalResult.WAITING;
Start := TRUE;

InterfaceAsPlainText.xhtml:
METHOD PUBLIC Start : BOOL
VAR_INPUT
	Key : ST_CoUnitFixtureKey;
	Mode : E_CoUnitTemporalMode;
	Now : LTIME;
	Duration : LTIME;
END_VAR

ST.xhtml:
IF NOT _active THEN Observe := E_CoUnitTemporalResult.REJECTED; RETURN; END_IF
IF (Key.RunId <> _key.RunId) OR (Key.SuiteId <> _key.SuiteId) OR (Key.CaseId <> _key.CaseId)
	OR (Key.RowKey <> _key.RowKey) OR (Key.AttemptId <> _key.AttemptId) OR (Key.StepId <> _key.StepId) THEN
	Observe := E_CoUnitTemporalResult.REJECTED;
	RETURN;
END_IF
Resolved := FALSE;
IF State <> E_CoUnitTemporalResult.WAITING THEN Observe := State; RETURN; END_IF
IF (Now < _lastNow) OR (Now < LTIME#0ns) THEN Observe := E_CoUnitTemporalResult.REJECTED; RETURN; END_IF
_lastNow := Now;
IF Cancel THEN
	State := E_CoUnitTemporalResult.CANCELLED;
ELSIF (_mode = E_CoUnitTemporalMode.EVENTUALLY_TRUE) OR (_mode = E_CoUnitTemporalMode.STEP) THEN
	IF Now > _deadline THEN State := E_CoUnitTemporalResult.FAILED;
	ELSIF Condition THEN State := E_CoUnitTemporalResult.PASSED;
	ELSIF Now >= _deadline THEN State := E_CoUnitTemporalResult.FAILED; END_IF
ELSIF _mode = E_CoUnitTemporalMode.REMAINS_TRUE THEN
	IF NOT Condition THEN State := E_CoUnitTemporalResult.FAILED;
	ELSIF Now >= _deadline THEN State := E_CoUnitTemporalResult.PASSED; END_IF
ELSIF _mode = E_CoUnitTemporalMode.REMAINS_FALSE THEN
	IF Condition THEN State := E_CoUnitTemporalResult.FAILED;
	ELSIF Now >= _deadline THEN State := E_CoUnitTemporalResult.PASSED; END_IF
END_IF
IF State <> E_CoUnitTemporalResult.WAITING THEN Resolved := TRUE; END_IF
Observe := State;

