	_callback.CleanupResult := E_CoUnitFixtureCallback.PASSED;
	_binding := _callback;
	_setupFailureSuppressedBody := _fixture.Start(Key := _fixtureKey, Fixture := _binding, Now := LTIME#0ns, PhaseTimeout := LTIME#10ns, CleanupBudget := LTIME#10ns);
	_stage := 7;
