	_fixture.Execute(Key := _fixtureKey, Now := LTIME#41ns, Cancel := FALSE);
	_stage := 21;
21:
	_fixture.Execute(Key := _fixtureKey, Now := LTIME#42ns, Cancel := FALSE);
