PROGRAM PRG_Qualification
VAR_OUTPUT
	Done : BOOL;
	OraclePass : BOOL;
	FailedCheck : UINT;
END_VAR
VAR
	_stage : UINT;
	_now : LTIME;
	_key : ST_CoUnitFixtureKey;
	_staleKey : ST_CoUnitFixtureKey;
	_temporal : FB_CoUnitExpectation;
